package com.yeyamo_mobile.api.notification_service.application;
import com.fasterxml.jackson.databind.ObjectMapper;import com.yeyamo_mobile.api.notification_service.infrastructure.messaging.UserActivityClient;import com.yeyamo_mobile.api.notification_service.infrastructure.persistence.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.time.temporal.ChronoUnit;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class ReengagementDigestService{private final UserActivityClient activity;private final SpringNotificationRepository notifications;private final SpringPreferenceRepository preferences;private final ReengagementStateRepository states;private final NotificationApplicationService service;private final ObjectMapper mapper;private final boolean enabled;private final int inactiveDays;private final int cooldownDays;
 public ReengagementDigestService(UserActivityClient a,SpringNotificationRepository n,SpringPreferenceRepository p,ReengagementStateRepository s,NotificationApplicationService service,ObjectMapper mapper,@Value("${yeyamo.reengagement.enabled:false}")boolean enabled,@Value("${yeyamo.reengagement.inactive-days:7}")int inactiveDays,@Value("${yeyamo.reengagement.cooldown-days:7}")int cooldownDays){activity=a;notifications=n;preferences=p;states=s;this.service=service;this.mapper=mapper;this.enabled=enabled;this.inactiveDays=Math.max(1,inactiveDays);this.cooldownDays=Math.max(1,cooldownDays);}
 @Scheduled(fixedDelayString="${yeyamo.reengagement.scan-delay-ms:21600000}") public void scan(){if(!enabled)return;Instant now=Instant.now();for(String user:activity.inactive(now.minus(inactiveDays,ChronoUnit.DAYS),500))process(user,now);}
 @Transactional public void process(String user,Instant now){var pref=preferences.findById(user).orElse(null);if(pref==null||!pref.isEmailEnabled()||pref.getEmailAddress()==null)return;var state=states.findById(user).orElse(null);if(state!=null&&state.getLastSentAt().plus(cooldownDays,ChronoUnit.DAYS).isAfter(now))return;Instant after=state==null?now.minus(inactiveDays,ChronoUnit.DAYS):state.getLastSentAt();var rows=notifications.countMeaningfulUnread(user,after);long total=rows.stream().mapToLong(r->((Number)r[1]).longValue()).sum();if(total==0)return;Map<String,String> vars=new LinkedHashMap<>();vars.put("total",Long.toString(total));vars.put("summary",summary(rows));UUID eventId=UUID.nameUUIDFromBytes(("reengagement:"+user+":"+after).getBytes(StandardCharsets.UTF_8));try{service.create(new NotificationIntent(eventId,"REENGAGEMENT_DIGEST",user,pref.getEmailAddress(),vars,mapper.writeValueAsString(Map.of("type","REENGAGEMENT_DIGEST","count",total))));}catch(Exception e){throw new IllegalStateException("REENGAGEMENT_DIGEST_CREATE_FAILED",e);}if(state==null)states.save(new ReengagementStateEntity(user,now));else{state.setLastSentAt(now);states.save(state);}}
 private String summary(List<Object[]> rows){return rows.stream().map(r->r[1]+" "+label(String.valueOf(r[0]))).sorted().reduce((a,b)->a+", "+b).orElse("");}private String label(String type){return switch(type){case "interaction.like.added"->"mentions J’aime";case "interaction.comment.created"->"réponses";case "social.followed"->"nouveaux abonnés";case "messaging.message.sent"->"nouveaux messages";default->"nouvelles activités";};}}
